UPDATE magnet_v2_engine_session s
JOIN magnet_v2_download_task t ON t.id = #{taskId}
SET s.active_task_id = #{taskId},
    s.owner_user_id = #{userId},
    s.revision = s.revision + 1,
    s.updated_at = CURRENT_TIMESTAMP(6)
WHERE s.resource_id = #{resourceId}
  AND s.active_task_id IS NULL
  AND t.user_id = #{userId}
  AND t.resource_id = #{resourceId}
  AND t.deleted = 0
  AND t.status IN ('CREATED', 'QUEUED', 'STARTING', 'DOWNLOADING', 'VERIFYING', 'RETRY_WAIT', 'REPAIRING')
